CREATE OR REPLACE FUNCTION public.owns_salon(_salon uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.salons WHERE id=_salon AND owner_id=auth.uid()) AND public.salon_access_allowed(_salon) $$;
CREATE OR REPLACE FUNCTION public.manages_salon(_salon uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'super_admin') OR (public.salon_access_allowed(_salon) AND (public.owns_salon(_salon) OR EXISTS(SELECT 1 FROM public.salon_members WHERE salon_id=_salon AND user_id=auth.uid() AND access='ADMIN'))) $$;
CREATE OR REPLACE FUNCTION public.belongs_salon(_salon uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'super_admin') OR (public.salon_access_allowed(_salon) AND (public.manages_salon(_salon) OR EXISTS(SELECT 1 FROM public.salon_members WHERE salon_id=_salon AND user_id=auth.uid()))) $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['salons','appointments','professionals','professions','services','config_agente_secretario','salon_connections','salon_clients','team_messages','supplier_brands','supplier_products','supplier_orders','month_closings','memoria_ia','fila_mensagens_ia','lead_conversations','whatsapp_outbound','reseller_leads','reseller_ai_settings'] LOOP EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t); EXECUTE format('CREATE POLICY master_global_read ON public.%I FOR SELECT TO authenticated USING (public.has_role(auth.uid(),''super_admin''))',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.public_salon_identity(_salon uuid) RETURNS TABLE(id uuid,name text,logo_url text,brand_color text,name_article text,nome_agente text,genero text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.id,s.name,s.logo_url,s.brand_color,s.name_article,c.nome_agente,c.genero FROM public.salons s LEFT JOIN public.config_agente_secretario c ON c.salon_id=s.id WHERE s.id=_salon AND s.status='ativo' AND public.salon_access_allowed(s.id) $$;